'use strict';

const input = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);

const prefixes = Array.from({ length: 11 }, () => new Set());
const suffixes = Array.from({ length: 11 }, () => new Set());
const substrings = Array.from({ length: 11 }, () => new Set());

for (let i = 1; i <= n; i++) {
  const word = input[i];
  const length = word.length;
  let invalid = substrings[length].has(word);

  for (let split = 1; !invalid && split < length; split++) {
    if (
      suffixes[split].has(word.slice(0, split)) &&
      prefixes[length - split].has(word.slice(split))
    ) {
      invalid = true;
    }
  }

  if (invalid) {
    console.log(word);
    process.exit(0);
  }

  for (let len = 1; len <= length; len++) {
    prefixes[len].add(word.slice(0, len));
    suffixes[len].add(word.slice(length - len));
  }

  for (let len = 1; len <= length; len++) {
    for (let start = 0; start + len <= length; start++) {
      substrings[len].add(word.slice(start, start + len));
    }
  }
}

console.log('ok');
